      const nsDecl = NS.map((id) => { const q = HP.allPresets().find((z) => z.id === id);
        return q ? { id, kFrame: q.physics.kFrame, geoPN: q.physics.geoPN, cls: q.sampleClass } : null; });
      // ③ 診断コピー(器と同じ作り方 —— sampleClass を principle にし台帳と claims を外す)
