          if (r.capState !== 'ok') capState = r.capState;
          const T = totals(bs, P, L, E);
          wP = Math.max(wP, Math.hypot(T.P[0] - T0.P[0], T.P[1] - T0.P[1]));
          wL = Math.max(wL, Math.abs(T.L - T0.L));
          wE = Math.max(wE, Math.abs(T.E - T0.E));
