      out.abBtn = !!btn;
      if (btn) { btn.click();
        out.abPhys = !!(ab && ab.simB && ab.simB.params.cLight === 30
          && Math.abs(((typeof ab.simB.params.kappaT === 'number')
            ? 1 / ab.simB.params.kappaT : ab.simB.params.Kt) - 134.85166317) < 1e-6);   // 第128便: κ 正準世代は 1/κ で読む
        abStop(); }
