          o.choiceDist[ch] = (o.choiceDist[ch] || 0) + 1;
          if (!(p.physics.geoPN > 0)) o.choiceDist0[ch] = (o.choiceDist0[ch] || 0) + 1;
          if (GEO0_CHOICES.indexOf(ch) < 0) o.bad.push(p.id + ': 選択 ' + ch);
          if (!pv.ok || pv.changes) o.bad.push(p.id + ': いまの選択の適用が no-op でない');
