          HP.setLang('en'); const en = (modeSettingIssues(x1, op1).find((z) => z.code === 'geo1Fitted') || {}).message || ''; HP.setLang('ja');
          o.lang.geo1Fitted = ja.length > 10 && en.length > 10 && ja !== en;
          if (!o.lang.geo1Fitted) o.bad.push('⑨ geo1Fitted の ja/en');
