      o.lang = !!zEn && msgJa.length > 20 && zEn.message.length > 20 && msgJa !== zEn.message && /fitRecord/.test(msgJa) && /fitRecord/.test(zEn.message);
      if (!o.lang) o.bad.push('(ii) geo1Fitted の ja/en の文');
