          for (const k of ['t', 'n', 'resPx', 'resPy', 'resL', 'radE', 'radL', 'coreWork', 'inertialDragN', 'inertialDragWork']) { const v = S[k]; if (typeof v === 'number') push(v); }
          if (S.rdPrevX) for (let i = 0; i < S.n; i++) push(S.rdPrevX[i]);
